-- UNSUPPORTED: licensed/staffed bed capacity or midnight census needed for an occupancy rate (no bed, census or capacity stream; organization entities carry no bed counts). Diagnostic returns prerequisite_available = 0 when no such stream (and no such field) has been received.
SELECT CASE WHEN EXISTS (SELECT 1 FROM records WHERE stream LIKE '%bed%' OR stream LIKE '%census%' OR stream LIKE '%capacity%') OR EXISTS (SELECT 1 FROM source_entities WHERE json_extract(payload,'$.licensed_beds') IS NOT NULL OR json_extract(payload,'$.staffed_beds') IS NOT NULL OR json_extract(payload,'$.bed_count') IS NOT NULL) THEN 1 ELSE 0 END AS prerequisite_available;
